function validateSignup(name, age) {
  const errors = {};
  if (name.trim() === "") errors.name = "Enter your name";
  const text = age.trim();
  if (text === "") errors.age = "Enter your age";              // check empty BEFORE Number()
  else if (Number.isNaN(Number(text))) errors.age = "Age must be a number";
  else if (Number(text) < 5 || Number(text) > 120) errors.age = "Age must be between 5 and 120";
  return errors;
}

function showErrors(errors) {
  for (const field of ["name", "age"]) {
    const message = errors[field] || "";                       // "" clears an old message
    document.getElementById(field + "-error").textContent = message;
    document.getElementById(field).classList.toggle("invalid", message !== "");
  }
}

document.getElementById("signup").addEventListener("submit", (event) => {
  event.preventDefault();
  const errors = validateSignup(document.getElementById("name").value, document.getElementById("age").value);
  showErrors(errors);
  if (Object.keys(errors).length === 0) document.getElementById("done").textContent = "Welcome!";
});

