function validateHarvest(farmer, kg) {
  const errors = {};
  if (String(farmer).trim() === "") errors.farmer = "Enter the farmer's name";
  const text = String(kg).trim();
  const n = Number(text);
  if (text === "") errors.kg = "Enter the kg";
  else if (Number.isNaN(n)) errors.kg = "kg must be a number";
  else if (n < 1 || n > 5000) errors.kg = "kg must be between 1 and 5000";
  return errors;
}

function showErrors(errors) {
  for (const field of ["farmer", "kg"]) {
    const message = errors[field] || "";   // "" clears an old message
    document.getElementById(field + "-error").textContent = message;
    document.getElementById(field).classList.toggle("invalid", message !== "");
  }
}

const form = document.getElementById("harvest-form");
form.addEventListener("submit", (event) => {
  event.preventDefault();
  const farmerBox = document.getElementById("farmer");
  const kgBox = document.getElementById("kg");
  const errors = validateHarvest(farmerBox.value, kgBox.value);
  showErrors(errors);
  if (Object.keys(errors).length > 0) return;

  document.getElementById("saved").textContent = `Saved ${Number(kgBox.value)} kg for ${farmerBox.value.trim()}`;
  farmerBox.value = "";
  kgBox.value = "";
});
